from z3 import *

# Number of vertices
n = 22

# Create boolean variables for each edge (i,j) where i < j
# We'll index edges as (i,j) with 0 <= i < j < n
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f"e_{i}_{j}")

solver = Solver()

# Constraint: No red K_4 (no 4 vertices with all edges red/False)
# For each 4-tuple, at least one edge must be blue/True
from itertools import combinations

count_4 = 0
for quad in combinations(range(n), 4):
    # All 6 edges among these 4 vertices
    edge_vars = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = quad[i], quad[j]
            if u > v:
                u, v = v, u
            edge_vars.append(edges[(u,v)])
    # At least one must be True (blue)
    solver.add(Or(edge_vars))
    count_4 += 1

print(f"Added {count_4} constraints for no red K_4")

# Constraint: No blue K_5 (no 5 vertices with all edges blue/True)
# For each 5-tuple, at least one edge must be red/False
count_5 = 0
for quint in combinations(range(n), 5):
    edge_vars = []
    for i in range(5):
        for j in range(i+1, 5):
            u, v = quint[i], quint[j]
            if u > v:
                u, v = v, u
            edge_vars.append(edges[(u,v)])
    # At least one must be False (red)
    solver.add(Or([Not(e) for e in edge_vars]))
    count_5 += 1

print(f"Added {count_5} constraints for no blue K_5")

print("Solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    # Extract solution in lexicographic order of (i,j)
    solution = []
    for i in range(n):
        for j in range(i+1, n):
            val = m[edges[(i,j)]]
            # True means blue (1), False means red (0)
            solution.append(1 if val else 0)
    print(f"Solution found with {len(solution)} edges")
    print(f"First 20 values: {solution[:20]}")

    # Verify the solution
    # Check no red K_4
    red_k4_found = False
    for quad in combinations(range(n), 4):
        all_red = True
        for i in range(4):
            for j in range(i+1, 4):
                u, v = quad[i], quad[j]
                if u > v:
                    u, v = v, u
                idx = 0
                for ii in range(n):
                    for jj in range(ii+1, n):
                        if ii == u and jj == v:
                            break
                        idx += 1
                    if ii == u:
                        break
                if solution[idx] == 1:  # blue
                    all_red = False
                    break
            if not all_red:
                break
        if all_red:
            red_k4_found = True
            print(f"Red K_4 found at {quad}")
            break

    if not red_k4_found:
        print("No red K_4 found - good!")

    # Check no blue K_5
    blue_k5_found = False
    for quint in combinations(range(n), 5):
        all_blue = True
        for i in range(5):
            for j in range(i+1, 5):
                u, v = quint[i], quint[j]
                if u > v:
                    u, v = v, u
                idx = 0
                for ii in range(n):
                    for jj in range(ii+1, n):
                        if ii == u and jj == v:
                            break
                        idx += 1
                    if ii == u:
                        break
                if solution[idx] == 0:  # red
                    all_blue = False
                    break
            if not all_blue:
                break
        if all_blue:
            blue_k5_found = True
            print(f"Blue K_5 found at {quint}")
            break

    if not blue_k5_found:
        print("No blue K_5 found - good!")

    # Save solution
    with open("solution.txt", "w") as f:
        f.write(",".join(map(str, solution)))
    print("Solution saved to solution.txt")

from pysat.solvers import Glucose3
from itertools import combinations

n = 22

# Number of edges = n*(n-1)/2 = 22*21/2 = 231
num_edges = n * (n - 1) // 2
print(f"Number of edges: {num_edges}")

# Map each edge (i,j) with i<j to a variable index 1..231
edge_to_var = {}
var_to_edge = {}
var_idx = 1
for i in range(n):
    for j in range(i+1, n):
        edge_to_var[(i,j)] = var_idx
        var_to_edge[var_idx] = (i,j)
        var_idx += 1

solver = Glucose3()

# Add clauses: no red K_4
# For each 4-tuple, at least one edge must be blue (variable = True)
count_4 = 0
for quad in combinations(range(n), 4):
    clause = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = quad[i], quad[j]
            if u > v:
                u, v = v, u
            clause.append(edge_to_var[(u,v)])
    solver.add_clause(clause)
    count_4 += 1

print(f"Added {count_4} clauses for no red K_4")

# Add clauses: no blue K_5
# For each 5-tuple, at least one edge must be red (variable = False)
count_5 = 0
for quint in combinations(range(n), 5):
    clause = []
    for i in range(5):
        for j in range(i+1, 5):
            u, v = quint[i], quint[j]
            if u > v:
                u, v = v, u
            clause.append(-edge_to_var[(u,v)])
    solver.add_clause(clause)
    count_5 += 1

print(f"Added {count_5} clauses for no blue K_5")

print("Solving...")
result = solver.solve()
print(f"Result: {result}")

if result:
    model = solver.get_model()
    solution = []
    for i in range(n):
        for j in range(i+1, n):
            var = edge_to_var[(i,j)]
            # Positive means True (blue=1), negative means False (red=0)
            solution.append(1 if var in model else 0)

    print(f"Solution length: {len(solution)}")
    print(f"First 30 values: {solution[:30]}")

    # Verify
    red_k4 = False
    for quad in combinations(range(n), 4):
        all_red = True
        for i in range(4):
            for j in range(i+1, 4):
                u, v = quad[i], quad[j]
                if u > v:
                    u, v = v, u
                if solution[edge_to_var[(u,v)] - 1] == 1:
                    all_red = False
                    break
            if not all_red:
                break
        if all_red:
            red_k4 = True
            print(f"ERROR: Red K_4 at {quad}")
            break

    blue_k5 = False
    for quint in combinations(range(n), 5):
        all_blue = True
        for i in range(5):
            for j in range(i+1, 5):
                u, v = quint[i], quint[j]
                if u > v:
                    u, v = v, u
                if solution[edge_to_var[(u,v)] - 1] == 0:
                    all_blue = False
                    break
            if not all_blue:
                break
        if all_blue:
            blue_k5 = True
            print(f"ERROR: Blue K_5 at {quint}")
            break

    if not red_k4 and not blue_k5:
        print("Solution verified!")
        print(solution)
else:
    print("UNSATISFIABLE")

